"use strict";
// Semantic arena initialization. Inputs are executable/platform parameters;
// subsequent allocations and growth must be generated by resource callers.
class OriginalResourceStartup {
  static memory({dataSegmentRelative,stackPointer,stackBias,configurationBytes,screenHeight,environment}){
    if(!Array.isArray(environment)||environment.some(s=>typeof s!=='string'||!s.length||Array.from(s).some(c=>c.charCodeAt(0)<1||c.charCodeAt(0)>127))||!Number.isInteger(configurationBytes)||configurationBytes<0||!Number.isInteger(screenHeight)||screenHeight<=0)throw new Error("Invalid original startup resources");
    const environmentBytes=1+environment.reduce((n,s)=>n+s.length+1,0);
    const platform=OriginalDOSMemory.treehouse({dataSegmentRelative,environmentBytes:Math.max(256,environmentBytes+83)});
    const near=new OriginalNearHeap({...this.near({stackPointer,stackBias}),growth:{limit:65536,quantum:1024}});
    const environmentPointer=near.allocate(environmentBytes),environmentIndex=near.allocate(2*(environment.length+1));
    near.growth.quantum=8192;
    // The launch configuration owns max(file length,28) bytes. VGA then
    // allocates one 16-bit scanline offset for each row of its screen.
    const configuration=near.allocate(Math.max(28,configurationBytes));
    const arena=this.allocateArena(platform.dos,platform.dataSegment);
    const scanlines=near.allocate(2*screenHeight);
    const memory=new OriginalMemory({heap:arena.heap,arena,dos:platform.dos,near:{...near.snapshot(),growth:near.growth}});
    return {...platform,memory,environmentPointer,environmentIndex,configuration,scanlines};
  }
  static near({stackPointer,stackBias}){
    if([stackPointer,stackBias].some(v=>!Number.isInteger(v)||v<0||v>65535)||stackPointer+stackBias>65535)throw new Error("Invalid original startup stack extent");
    // Resident 0076..00DB: align SP, then push the terminator and empty hole.
    const top=(stackPointer+stackBias)&0xfffe,start=top-4,end=top-2;
    if(start<0)throw new Error("Original startup stack cannot hold heap headers");
    return {blocks:[{address:start,size:0,free:true},{address:end,size:65534,free:false}],start,search:start,end};
  }
  static arena({segment,paragraphs}){
    if(!Number.isInteger(segment)||segment<=0||!Number.isInteger(paragraphs)||paragraphs<3||segment+paragraphs>0xa000)throw new Error("Invalid original conventional arena extent");
    // Resident 687B initializes a 22-byte control record, a free block and
    // a six-byte terminator. DOS allocation results are platform inputs.
    const control=segment*16,start=control+22,end=control+paragraphs*16-6;
    return {
      control,paragraphs,committedParagraphs:paragraphs,emsSegment:0,closed:false,
      heap:{blocks:[{address:start,size:end-start,flags:0,padding:0},{address:end,size:6,flags:0x4000,padding:0}],handles:[],search:start}
    };
  }
  static allocateArena(dos,dataSegment,requestedBytes=0){
    if(!Number.isInteger(dataSegment)||dataSegment<0||dataSegment>65535||!Number.isInteger(requestedBytes)||requestedBytes<0||requestedBytes>0xffffffff)throw new Error("Invalid resource arena initialization request");
    const wanted=Math.max(3,Math.min(65535,Math.ceil(requestedBytes/16)));let paragraphs=wanted;
    for(let attempts=0;attempts<65536;attempts++){
      let allocation=dos.allocate(paragraphs);
      if(!allocation.ok){if(!allocation.paragraphs)throw new Error("No conventional memory for resource arena");paragraphs=allocation.paragraphs;allocation=dos.allocate(paragraphs);}
      if(!allocation.ok)throw new Error("Cannot allocate conventional resource arena");
      if(allocation.segment<=dataSegment){dos.free(allocation.segment);paragraphs++;continue;}
      const arena=this.arena(allocation);
      if(arena.paragraphs<wanted)this.growWithDOS(arena,16*(wanted-arena.paragraphs),dos);
      return arena;
    }
    throw new Error("Resource arena allocation failed to terminate");
  }
  static growWithDOS(arena,requestedBytes,dos){
    if(arena.closed)return 0;
    if(!Number.isInteger(requestedBytes)||requestedBytes<0||requestedBytes>0xffffffff)throw new Error("Invalid resource arena growth request");
    const paragraphs=Math.min(65535,arena.committedParagraphs+Math.min(65535,Math.ceil(requestedBytes/16)));
    let result=dos.resize(arena.control/16,paragraphs);
    if(!result.ok&&result.error===8)result=dos.resize(arena.control/16,result.paragraphs);
    if(!result.ok)throw new Error("Cannot resize conventional resource arena");
    return this.growArena(arena,requestedBytes,result.paragraphs);
  }
  static growArena(arena,requestedBytes,maximumParagraphs){
    if(!Number.isInteger(requestedBytes)||requestedBytes<0||requestedBytes>0xffffffff||!Number.isInteger(maximumParagraphs)||maximumParagraphs<arena.committedParagraphs||maximumParagraphs>65535||arena.control+16*maximumParagraphs>0xa0000)throw new Error("Invalid conventional arena growth request");
    if(arena.emsSegment)throw new Error("EMS arena growth is not reconstructed");
    if(arena.closed)return 0;
    // Resident 678B retries a failed DOS resize at the available size. A
    // partial or zero extension closes this conventional arena to growth.
    const requested=Math.min(65535,Math.ceil(requestedBytes/16));
    const target=Math.min(65535,arena.committedParagraphs+requested,maximumParagraphs);
    const paragraphs=target-arena.committedParagraphs,bytes=16*paragraphs;
    if(paragraphs){
      const terminal=arena.heap.blocks.at(-1);
      if(terminal.flags!==0x4000||terminal.size!==6)throw new Error("Invalid conventional arena terminator");
      terminal.flags=0;terminal.size=bytes;terminal.padding=0;
      arena.heap.blocks.push({address:terminal.address+bytes,size:6,flags:0x4000,padding:0});
      arena.committedParagraphs=target;arena.paragraphs+=paragraphs;
    }
    if(!paragraphs||paragraphs<requested)arena.closed=true;
    return bytes;
  }
}
